pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 1 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.withdraw(amount);
        // Rule: after withdrawing `amount`, the caller's credited balance is reduced,
        // so withdrawing any further amount (e.g. 1 wei) must revert.
        vm.prank(actor);
