// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        // keep d wide but leave room so that w > d/2 is representable
        uint256 d = bound(depositAmount, 1, type(uint256).max / 2);
        // w is more than half of the deposit: after withdrawing w, contract
        // holds d - w < w, so a mutant that still credits w cannot pay refund()
        uint256 w = bound(withdrawAmount, d / 2 + 1, d);

        vm.deal(actor, d);
        vm.prank(actor);
        c.deposit{value: d}();

        vm.prank(actor);
        c.withdraw(w);

        // In C, credited balance is d - w, so refund sends 0 and succeeds.
        // In M, credited balance is still w > d - w = address(c).balance,
        // so refund()'s transfer reverts.
        vm.prank(actor);
        bool ok;
        try c.refund() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

