pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposit, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(deposit >= 2 * amount);
        vm.assume(deposit <= address(this).balance + 1e30);

        Attacker attacker = new Attacker(c);
        vm.deal(address(this), deposit);
        attacker.go{value: deposit}(amount);

        // General rule: after a funded re-entrant attacker executes withdraw(amount),
        // exactly two payouts of `amount` have left the contract, so c retains
        // deposit - 2*amount. The reference C satisfies this for every admissible
        // input; the mutant (decrement before transfer) prevents the re-entrant
        // payout, leaving deposit - amount, and fails it.
        assertTrue(address(c).balance == deposit - 2 * amount);
    }
}

contract Attacker {
    C c;
    uint256 amt;
    constructor(C _c) { c = _c; }
    function go(uint256 a) external payable {
        amt = a;
        c.deposit{value: msg.value}();
        c.withdraw(a);
    }
    receive() external payable {
        if (address(c).balance >= amt) c.withdraw(amt);
    }
}

