pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 deposit_, uint256 amount) public {
        deposit_ = bound(deposit_, 1, 1e30);
        amount = bound(amount, 1, deposit_);

        vm.deal(address(attacker), deposit_);
        attacker.depositInto(deposit_);
        attacker.setThreshold(amount);

        bool ok;
        try attacker.attack(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Attacker {
    C c;
    uint256 threshold;

    constructor(C _c) {
        c = _c;
    }

    function depositInto(uint256 d) external payable {
        c.deposit{value: d}();
    }

    function setThreshold(uint256 t) external {
        threshold = t;
    }

    function attack(uint256 a) external {
        c.withdraw(a);
    }

    receive() external payable {
        // read balances[address(this)] from storage (slot 1 of C, private)
        bytes32 slot;
        address me = address(this);
        assembly {
            mstore(0, me)
            mstore(0x20, 1)
            slot := keccak(0, 0x40)
        }
        uint256 bal;
        assembly {
            bal := sload(slot)
        }
        if (bal < threshold) {
            revert();
        }
    }
}

