pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 d, uint256 a) public {
        // Admissible domain: a real positive deposit and a withdrawal strictly inside it.
        vm.assume(d > 0);
        vm.assume(a > 0 && a < d);

        Refunder attacker = new Refunder(c);
        vm.deal(address(attacker), d);

        // Attacker funds the contract and then withdraws `a`; its receive()
        // re-enters refund() during the payout (no-op on zero-value callbacks).
        attacker.fundAndWithdraw(d, a);

        bool ok = attacker.lastOk();
        uint256 bal = address(c).balance;

        // General rule: whenever a withdraw(a) against a funding deposit of d
        // completes successfully, the contract must be left holding exactly
        // d - a. In the reference the inner refund() pays out the full credited
        // balance, so the outer withdraw can only succeed in the degenerate case
        // where the payout is still consistent (balance stays d - a for any
        // succeeding run); in the mutant the balance is already zeroed before
        // the transfer, so the re-entrant refund drains the rest and a
        // "successful" withdraw leaves 0 instead of d - a.
        assertTrue(!ok || (bal == d - a));
    }
}

contract Refunder {
    C c;
    bool public lastOk;

    constructor(C _c) { c = _c; }

    function fundAndWithdraw(uint256 d, uint256 a) external {
        c.deposit{value: d}();
        try c.withdraw(a) {
            lastOk = true;
        } catch {
            lastOk = false;
        }
    }

    receive() external payable {
        if (msg.value > 0) {
            c.refund();
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint256 a, uint256 b) public {
        require(address(this).balance >= a + b);
        c.deposit{value: a}();
        c.deposit{value: b}();
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSelector(C.withdraw.selector, a + b));
        assert(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint256 amount) public {
        require(amount > 0);
        require(address(this).balance >= amount);
        uint256 before = address(c).balance;
        c.deposit{value: amount}();
        assert(address(c).balance == before + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint256 amount) public {
        require(amount > 0);
        require(address(this).balance >= amount);
        uint256 before = address(this).balance;
        c.deposit{value: amount}();
        c.withdraw(amount);
        assert(address(this).balance == before);
    }

    receive() external payable {}
    fallback() external payable {}
}
